#[test]
fn matches_observed_client_matrix() {
    for (name, body, requested, oauth, want) in CASES {
        let requested: Vec<String> = requested.iter().map(|s| s.to_string()).collect();
        let set = claude_requested_betas("", &requested);
        assert_eq!(claude_code_cli_betas(body.as_bytes(), &set, *oauth), *want, "{name}");
    }
}

#[test]
fn advisor_tool_beta_inserts_before_trailing_betas() {
    const HEAD: &str = "claude-code-20250219,oauth-2025-04-20,interleaved-thinking-2025-05-14,mid-conversation-system-2026-04-07";
    let cases = [
        (
            format!("{HEAD},afk-mode-2026-01-31,extended-cache-ttl-2025-04-11"),
            format!("{HEAD},advisor-tool-2026-03-01,afk-mode-2026-01-31,extended-cache-ttl-2025-04-11"),
        ),
        (
            format!("{HEAD},effort-2025-11-24,fallback-credit-2026-06-01,afk-mode-2026-01-31,extended-cache-ttl-2025-04-11"),
            format!("{HEAD},advisor-tool-2026-03-01,effort-2025-11-24,fallback-credit-2026-06-01,afk-mode-2026-01-31,extended-cache-ttl-2025-04-11"),
        ),
        (
            format!("{HEAD},advisor-tool-2026-03-01,effort-2025-11-24,afk-mode-2026-01-31"),
            format!("{HEAD},advisor-tool-2026-03-01,effort-2025-11-24,afk-mode-2026-01-31"),
        ),
        (HEAD.to_string(), format!("{HEAD},advisor-tool-2026-03-01")),
    ];
    for (betas, want) in cases {
        assert_eq!(with_claude_advisor_tool_beta(&betas), want);
    }
}
